css:
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: 80px;
  grid-auto-flow: dense;
  gap: 8px;
  padding: 12px;
}

.tile {
  padding: 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.hero {
  grid-column: span 2;
  grid-row: span 2;
}

.wide {
  grid-column: span 2;
}
